// recordRoutingQualityForRequest records one Execute call into the
// service's routing-quality store. ovr may be nil for non-overridden
// requests; when non-nil, the recorded record pointer is stashed onto the
// override context so the fan-out goroutine can back-write the
// post-execution outcome (success / stalled / failed / cancelled) once the
// final event arrives. The back-write is what makes the in-memory ring's
// outcome aggregates real rather than always-zero (ADR-006 §5).
func (s *service) recordRoutingQualityForRequest(ovr *overrideContext) {
	if s == nil || s.routingQuality == nil {
		return
	}
	now := time.Now().UTC()
	if ovr == nil {
		s.routingQuality.recordRequest(now, nil)
		return
	}
	payload := ovr.payload
	rec := s.routingQuality.recordRequest(now, &payload)
	ovr.record = rec
}

// stampOutcomeOnRecord copies the post-execution outcome into the ring
// record stored on ovr. Safe to call once after the override event is
// emitted (the channel send-receive between runExecute and the fan-out
// goroutine establishes happens-before, so plain field writes are race-free
// here).
func stampOutcomeOnRecord(rec *routingQualityRecord, outcome *ServiceOverrideOutcome) {
	if rec == nil || rec.inner == nil || outcome == nil {
		return
	}
	routingquality.StampOutcome(rec.inner, &routingquality.Outcome{Status: outcome.Status})
}

func toRoutingQualityOverride(ov ServiceOverrideData) *routingquality.OverrideData {
	out := &routingquality.OverrideData{
		AxesOverridden: append([]string(nil), ov.AxesOverridden...),
		MatchPerAxis:   make(map[string]bool, len(ov.MatchPerAxis)),
		PromptFeatures: routingquality.PromptFeatures{
			RequiresTools: ov.PromptFeatures.RequiresTools,
			Reasoning:     ov.PromptFeatures.Reasoning,
		},
	}
	for axis, match := range ov.MatchPerAxis {
		out.MatchPerAxis[axis] = match
	}
	if ov.PromptFeatures.EstimatedTokens != nil {
		tokens := *ov.PromptFeatures.EstimatedTokens
		out.PromptFeatures.EstimatedTokens = &tokens
	}
	if ov.Outcome != nil {
		out.Outcome = &routingquality.Outcome{Status: ov.Outcome.Status}
	}
	return out
}

func fromRoutingQualityMetrics(m routingquality.Metrics) RoutingQualityMetrics {
	out := RoutingQualityMetrics{
		AutoAcceptanceRate:       m.AutoAcceptanceRate,
		OverrideDisagreementRate: m.OverrideDisagreementRate,
		TotalRequests:            m.TotalRequests,
		TotalOverrides:           m.TotalOverrides,
	}
	if len(m.OverrideClassBreakdown) > 0 {
		out.OverrideClassBreakdown = make([]OverrideClassBucket, 0, len(m.OverrideClassBreakdown))
		for _, b := range m.OverrideClassBreakdown {
			out.OverrideClassBreakdown = append(out.OverrideClassBreakdown, OverrideClassBucket{
				PromptFeatureBucket: b.PromptFeatureBucket,
				Axis:                b.Axis,
				Match:               b.Match,
				Count:               b.Count,
				SuccessOutcomes:     b.SuccessOutcomes,
				StalledOutcomes:     b.StalledOutcomes,
				FailedOutcomes:      b.FailedOutcomes,
				CancelledOutcomes:   b.CancelledOutcomes,
				UnknownOutcomes:     b.UnknownOutcomes,
			})
		}
	}
	return out
}

package fizeau

import (
	"context"
	"sync/atomic"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/serviceimpl"
)

type executeRouteResolver interface {
	resolveExecuteRoute(ServiceExecuteRequest) (*RouteDecision, error)
}

type executeSessionLogOpener interface {
	openSessionLog(ServiceExecuteRequest, RouteDecision, string) *serviceSessionLog
}

type executeEventFanout interface {
	openSession(string)
	broadcastEvent(string, ServiceEvent)
	closeSession(string, ServiceEvent)
	wrapExecuteWithHub(string, chan ServiceEvent, *overrideContext, map[string]string) chan ServiceEvent
}

type executeRunnerInvoker interface {
	dispatchExecuteRun(context.Context, executeRunContext)
}

type executeRunContext struct {
	req      ServiceExecuteRequest
	decision RouteDecision
	meta     map[string]string
	out      chan<- ServiceEvent
	seq      *atomic.Int64
	start    time.Time
	sl       *serviceSessionLog
	session  string
}

func (s *service) executeRouteResolver() executeRouteResolver {
	return s
}

func (s *service) executeSessionLogOpener() executeSessionLogOpener {
	return s
}

func (s *service) executeEventFanout() executeEventFanout {
	return s.hub
}

func (s *service) executeRunnerInvoker() executeRunnerInvoker {
	return s
}

func (s *service) dispatchExecuteRun(ctx context.Context, run executeRunContext) {
	decision := serviceimpl.ExecuteRunnerDecision{
		Harness:  run.decision.Harness,
		Provider: run.decision.Provider,
		Model:    run.decision.Model,
	}
	serviceimpl.DispatchExecuteRun(ctx, serviceimpl.ExecuteDispatchRequest{
		Decision: decision,
		Started:  run.start,
	}, serviceimpl.ExecuteDispatchCallbacks{
		RunNative: func(ctx context.Context) {
			s.runNative(ctx, run.req, run.decision, run.meta, run.out, run.seq, run.start, run.sl, run.session)
		},
		RunSubprocess: func(ctx context.Context, runner harnesses.Harness) {
			s.runSubprocess(ctx, run.req, run.decision, run.meta, run.out, run.seq, run.start, run.sl, run.session, runner)
		},
		RunVirtual: func(ctx context.Context) {
			s.runVirtual(ctx, run.req, run.decision, run.meta, run.out, run.seq, run.start, run.sl, run.session)
		},
		RunScript: func(ctx context.Context) {
			s.runScript(ctx, run.req, run.decision, run.meta, run.out, run.seq, run.start, run.sl, run.session)
		},
		IsHTTPProvider: func(harness string) bool {
			cfg, ok := s.registry.Get(harness)
			return ok && cfg.IsHTTPProvider
		},
		Finalize: func(final harnesses.FinalData) {
			finalizeAndEmit(run.out, run.seq, run.meta, run.req, run.sl, final)
		},
	})
}

package fizeau

import (
	"context"
	"encoding/json"
	"errors"
	"sync/atomic"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
)

// overrideAxis* enumerates the three independently-tracked override axes.
const (
	overrideAxisHarness  = "harness"
	overrideAxisProvider = "provider"
	overrideAxisModel    = "model"
)

// overrideContext carries the per-Execute override-event payload from the
// service entrypoint through to the channel-fan-out goroutine, where the
// terminal outcome is stamped on right before the final event is forwarded.
//
// record points at the live in-memory ring entry for this request (set by
// Execute via recordRoutingQualityForRequest); the fan-out goroutine
// back-writes the outcome onto it when the override event fires so
// RouteStatus surfaces non-zero outcome aggregates.
//
// sl points at the request's session log (set in runExecute after
// openSessionLog); the fan-out goroutine writes the override event there
// so UsageReport can recompute routing-quality from persisted session logs
// across restarts and beyond the in-memory ring's bounded retention.
type overrideContext struct {
	payload ServiceOverrideData
	emitted atomic.Bool
	record  *routingQualityRecord
	sl      atomic.Pointer[serviceSessionLog]
}

// axesOverridden returns the canonical, ordered list of axes the caller
// pinned. Order is fixed (harness, provider, model) so consumers can
// compare across requests.
func axesOverridden(req ServiceExecuteRequest) []string {
	axes := make([]string, 0, 3)
	if req.Harness != "" {
		axes = append(axes, overrideAxisHarness)
	}
	if req.Provider != "" {
		axes = append(axes, overrideAxisProvider)
	}
	if req.Model != "" {
		axes = append(axes, overrideAxisModel)
	}
	return axes
}

// buildOverrideContext computes the override event payload for req, including
// the second (axes-stripped) ResolveRoute call. Returns nil when no override
// axis is set on the request.
//
// The auto-decision call is best-effort: if it fails (e.g., empty inputs
// after stripping leave nothing to resolve), the auto_decision and component
// fields are left zero. The override event still fires per ADR-006 §7.
func (s *service) buildOverrideContext(ctx context.Context, req ServiceExecuteRequest) *overrideContext {
	axes := axesOverridden(req)
	if len(axes) == 0 {
		return nil
	}

	userPin := ServiceOverridePin{
		Harness:  req.Harness,
		Provider: req.Provider,
		Model:    req.Model,
	}

	auto, autoScore, autoComps := s.resolveAutoDecisionForOverride(ctx, req, axes)

	matchPerAxis := make(map[string]bool, len(axes))
	for _, axis := range axes {
		switch axis {
		case overrideAxisHarness:
			matchPerAxis[axis] = userPin.Harness != "" && userPin.Harness == auto.Harness
		case overrideAxisProvider:
			matchPerAxis[axis] = userPin.Provider != "" && userPin.Provider == auto.Provider
		case overrideAxisModel:
			matchPerAxis[axis] = userPin.Model != "" && userPin.Model == auto.Model
		}
	}

	return &overrideContext{
		payload: ServiceOverrideData{
			UserPin:        userPin,
			AutoDecision:   auto,
			AxesOverridden: axes,
			MatchPerAxis:   matchPerAxis,
			AutoScore:      autoScore,
			AutoComponents: autoComps,
			PromptFeatures: buildPromptFeatures(req),
			ReasonHint:     overrideReasonHint(req),
		},
	}
}

// resolveAutoDecisionForOverride runs ResolveRoute with the override axes
// stripped to produce the unconstrained auto pick. Returns zero values when
// the resolution does not yield a usable decision.
func (s *service) resolveAutoDecisionForOverride(ctx context.Context, req ServiceExecuteRequest, axes []string) (ServiceOverridePin, float64, ServiceOverrideAutoComponents) {
	// Strip the overridden axes; keep all non-axis intent fields verbatim.
	// The non-axes branches are unreachable in practice (if the axis is in
	// `axes`, the field on req is non-empty), but we surface non-axis user
	// inputs explicitly so future axis additions are obvious here.
	stripped := RouteRequest{
		Profile:               req.Profile,
		ModelRef:              req.ModelRef,
		Reasoning:             req.Reasoning,
		Permissions:           req.Permissions,
		EstimatedPromptTokens: req.EstimatedPromptTokens,
		RequiresTools:         req.RequiresTools,
		CachePolicy:           req.CachePolicy,
	}
	if !stringIn(axes, overrideAxisHarness) {
		stripped.Harness = req.Harness
	}
	if !stringIn(axes, overrideAxisProvider) {
		stripped.Provider = req.Provider
	}
	if !stringIn(axes, overrideAxisModel) {
		stripped.Model = req.Model
	}

	dec, err := s.ResolveRoute(ctx, stripped)
	if err != nil || dec == nil || dec.Harness == "" {
		return ServiceOverridePin{}, 0, ServiceOverrideAutoComponents{}
	}
	auto := ServiceOverridePin{
		Harness:  dec.Harness,
		Provider: dec.Provider,
		Model:    dec.Model,
	}
	for _, c := range dec.Candidates {
		if !c.Eligible {
			continue
		}
		if c.Harness == dec.Harness && c.Provider == dec.Provider && c.Model == dec.Model {
			return auto, c.Score, ServiceOverrideAutoComponents{
				Power:            c.Components.Power,
				Cost:             c.Components.Cost,
				CostClass:        c.Components.CostClass,
				LatencyMS:        c.Components.LatencyMS,
				SpeedTPS:         c.Components.SpeedTPS,
				SuccessRate:      c.Components.SuccessRate,
				QuotaOK:          c.Components.QuotaOK,
				QuotaPercentUsed: c.Components.QuotaPercentUsed,
				QuotaTrend:       c.Components.QuotaTrend,
				Capability:       c.Components.Capability,
			}
		}
	}
	return auto, 0, ServiceOverrideAutoComponents{}
}

