		t.Fatalf("ResolveRoute: %v", err)
	}
	if dec.Harness != "codex" || dec.Model != "gpt-5.5" {
		t.Fatalf("ResolveRoute: got harness=%q model=%q, want codex gpt-5.5", dec.Harness, dec.Model)
	}
}

